use xiom.io;

use xiom.string;
fn main() -> Int {
  match string.str_to_int("100") {
    Ok(n) => io.println("Got: " + to_string(n)),
    Err(e) => io.println("Parse error"),
  };

  match string.str_to_int("notanumber") {
    Ok(n) => io.println("Got: " + to_string(n)),
    Err(e) => io.println("Failed: " + e.to_str()),
  };

  match string.str_to_int("-50") {
    Ok(n) => {
      if n < 0 { io.println(to_string(n * -1)); }
      else { io.println(to_string(n)); }
    },
    Err(e) => io.println("Parse error"),
  };

  let s1 = string.str_to_int("5").unwrap_or(0);
  let s2 = string.str_to_int("10").unwrap_or(0);
  let s3 = string.str_to_int("15").unwrap_or(0);
  io.println(to_string(s1 + s2 + s3));
  return 0;
}
